import {readFile,writeFile,mkdir,cp,rm} from "node:fs/promises";
import {stripTypeScriptTypes} from "node:module";
import path from "node:path";
// dist is generated by this script. Refuse to remove anything outside this checkout.
const project=process.cwd(),out=path.resolve(project,"dist");
if(path.dirname(out)!==project||path.basename(out)!=="dist")throw Error("Invalid build directory.");
await rm(out,{recursive:true,force:true});await mkdir(out,{recursive:true});
const domain=stripTypeScriptTypes(await readFile("lib/inventory.ts","utf8"),{mode:"strip"});
await writeFile("public/domain.mjs",domain);
await cp("public",out,{recursive:true});await cp("public/app.html",path.join(out,"index.html"));
console.log("Built portable static demo in dist/ (Netlify or Vercel).");
